const person = {
  name: "Lexi",
  age: 20,
  skills: ["HTML", "CSS"],
  greet() {
    return `Xin chào, tôi là ${this.name}`;
  },
};

console.log(person.name);          // truy cập bằng dấu chấm
console.log(person["age"]);        // hoặc bằng ngoặc vuông
person.city = "Hà Nội";            // thêm thuộc tính
console.log(person.greet());

const { name, age } = person;      // destructuring
console.log(name, age);
console.log(Object.keys(person));  // tên các thuộc tính

